<?php $page='reports';$title='Reports & Summary';require_once __DIR__.'/includes/functions.php';require_login();$uid=$_SESSION['user_id'];$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$start=$month.'-01';$end=date('Y-m-t',strtotime($start));$tot=get_totals($pdo,$uid,$start,$end);$q=$pdo->prepare("SELECT category,SUM(amount) total FROM transactions WHERE user_id=? AND type='expense' AND transaction_date BETWEEN ? AND ? GROUP BY category ORDER BY total DESC");$q->execute([$uid,$start,$end]);$cats=$q->fetchAll();$budgetQ=$pdo->prepare("SELECT amount FROM budgets WHERE user_id=? AND period='monthly' AND start_date<=? ORDER BY start_date DESC LIMIT 1");$budgetQ->execute([$uid,$start]);$budget=(float)($budgetQ->fetchColumn()?:0);require 'includes/header.php';?>
<div class="page-head"><div><h1>Reports &amp; Summary</h1><p>Daily, weekly/monthly summaries and spending by category.</p></div><form method="get"><input type="month" name="month" value="<?=e($month)?>"><button class="btn">View</button></form></div><div class="two-col"><div class="card"><h3>Financial Summary — <?=e(date('F Y',strtotime($start)))?></h3><p>Total Income: <strong><?=money($tot['income'])?></strong></p><p>Total Expenses: <strong><?=money($tot['expense'])?></strong></p><p>Budget: <strong><?=money($budget)?></strong></p><p>Remaining: <strong><?=money($budget-$tot['expense'])?></strong></p><p>Net Cash Flow: <strong><?=money($tot['income']-$tot['expense'])?></strong></p></div><div class="card"><h3>Spending by Category</h3><?php $max=max(array_column($cats,'total')?:[1]);foreach($cats as $c):?><div class="bar-row"><small><?=e($c['category'])?> — <?=money($c['total'])?></small><div class="progress"><span style="width:<?=min(100,((float)$c['total']/$max)*100)?>%"></span></div></div><?php endforeach;if(!$cats):?><p class="empty">No expenses recorded for this month.</p><?php endif;?></div></div><div class="card"><h3>Monthly Transaction Details</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Description</th><th>Category</th><th>Amount</th></tr></thead><tbody><?php $q=$pdo->prepare('SELECT * FROM transactions WHERE user_id=? AND transaction_date BETWEEN ? AND ? ORDER BY transaction_date DESC');$q->execute([$uid,$start,$end]);foreach($q as $r):?><tr><td><?=e($r['transaction_date'])?></td><td><?=e(ucfirst($r['type']))?></td><td><?=e($r['description'])?></td><td><?=e($r['category'])?></td><td><?=money($r['amount'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>
